package com.example.rokidkeyboardbridge;
import org.json.*;
/** Only repeats provider/user-selected information. Never infers a safe crossing or platform. */
public final class NavigationJourneyCues {
 private String route="",maneuver="",headingRoute="";private boolean recovery,headingAnnounced,waitingAnnounced;
 public synchronized String status(String identity,String revision,boolean recovering,boolean walking,boolean heading){if(!identity.equals(route)){route=identity;recovery=false;headingAnnounced=waitingAnnounced=false;}if(!revision.equals(headingRoute)){headingRoute=revision;headingAnnounced=waitingAnnounced=false;}if(recovering){if(recovery)return "";recovery=true;return "経路を確認中です。新しい経路が確認できてから案内します。";}recovery=false;if(!walking)return "";if(!heading&&!waitingAnnounced){waitingAnnounced=true;return "出発方向を確認中です。左右の案内は移動方向を確認してから行います。";}if(heading&&!headingAnnounced){headingAnnounced=true;return "移動方向を確認できました。";}return "";}
 public synchronized String infrastructure(String key,String instruction,String secondary,String distance,boolean fresh){double m=NavigationTurnCue.metres(distance);if(!fresh||m<0||m>30||key.equals(maneuver))return "";String s=instruction==null?"":instruction,t=secondary==null?"":secondary;if(!s.matches(".*(横断歩道|歩道橋|地下道|階段|エレベーター).*"))s=t;if(!s.matches(".*(横断歩道|歩道橋|地下道|階段|エレベーター).*"))return "";maneuver=key;return "経路情報："+NavigationConversation.concise(s);}
 public static String entry(String selected,boolean near){return !near?"":selected==null||selected.trim().isEmpty()?"入口・出口は未確認です":"指定した入口・出口："+NavigationConversation.concise(selected);}
 public static String action(JSONObject journey,String phase){return action(journey,phase,"");}
 public static String action(JSONObject journey,String phase,String mode){if("FIRST_MILE".equals(phase))return "次にすること：乗車地点まで移動";if("BOARDING".equals(phase))return "次にすること：乗車を確認";if("LAST_MILE".equals(phase))return "次にすること：目的地まで移動";if(journey==null)return "";JSONObject l=journey.optJSONObject("currentLeg");if("TRANSIT_LEG".equals(phase))return "次にすること：降車地点を確認"+(l==null||l.optString("arrivalStop").isEmpty()?"":"（"+l.optString("arrivalStop")+"）");if(l==null||!journey.optBoolean("positionConfirmed"))return "";String text=l.optString("instruction");if(text.matches(".*(番線|出口).*"))return "経路情報："+NavigationConversation.concise(text);String travel=l.optString("travelMode").toUpperCase(java.util.Locale.ROOT);String label;
 switch(travel){case "BICYCLE":case "BICYCLING":case "BICYCLING_MODE":label="自転車移動";break;case "DRIVE":case "DRIVING":label="車で移動";break;case "WALK":case "WALKING":label="徒歩移動";break;case "TRANSIT":return "乗車・降車は操作で確認";default:label="bicycling".equals(mode)?"自転車移動":"driving".equals(mode)?"車で移動":"walking".equals(mode)?"徒歩移動":"移動手段未確認";}
 return "現在の区間："+label;}
}
